"use client";

import {
    User,
    ShieldCheck,
    Image as ImageIcon,
    MapPin,
    Lock,
    CreditCard,
    Save,
    AlertCircle,
    FileText
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useState, useEffect } from "react";
import { useSimulation } from "@/components/SimulationProvider";
import { supabase } from "@/lib/supabase";

export default function SettingsPage() {
    const { currentUser, updateUser } = useSimulation();
    const [activeTab, setActiveTab] = useState("perfil");
    const [loading, setLoading] = useState(false);
    const [success, setSuccess] = useState(false);

    // Form states
    const [name, setName] = useState("");
    const [phone, setPhone] = useState("");
    const [avatarUrl, setAvatarUrl] = useState("");
    const [doc, setDoc] = useState("");
    const [companyName, setCompanyName] = useState("");
    const [stateRegistration, setStateRegistration] = useState("");
    const [pixKey, setPixKey] = useState("");
    const [addressZip, setAddressZip] = useState("");
    const [addressStreet, setAddressStreet] = useState("");
    const [addressNumber, setAddressNumber] = useState("");
    const [addressComplement, setAddressComplement] = useState("");
    const [addressNeighborhood, setAddressNeighborhood] = useState("");
    const [addressCity, setAddressCity] = useState("");
    const [addressState, setAddressState] = useState("");

    // Sync form when currentUser changes
    useEffect(() => {
        if (currentUser) {
            setName(currentUser.name || "");
            setPhone(currentUser.phone || "");
            setAvatarUrl(currentUser.avatar || "");
            setDoc(currentUser.doc || "");
            setCompanyName(currentUser.company_name || "");
            setStateRegistration(currentUser.state_registration || "");
            setPixKey(currentUser.pix_key || "");
            setAddressZip(currentUser.address_zip || "");
            setAddressStreet(currentUser.address_street || "");
            setAddressNumber(currentUser.address_number || "");
            setAddressComplement(currentUser.address_complement || "");
            setAddressNeighborhood(currentUser.address_neighborhood || "");
            setAddressCity(currentUser.address_city || "");
            setAddressState(currentUser.address_state || "");
        }
    }, [currentUser]);

    const handleSaveProfile = async () => {
        setLoading(true);
        setSuccess(false);

        try {
            const { data: { session } } = await supabase.auth.getSession();

            if (!session) throw new Error("Usuário não autenticado");

            const { data: updated, error } = await supabase
                .from('profiles')
                .update({
                    full_name: name,
                    phone,
                    avatar_url: avatarUrl,
                    doc,
                    company_name: companyName,
                    state_registration: stateRegistration,
                    pix_key: pixKey,
                    address_zip: addressZip,
                    address_street: addressStreet,
                    address_number: addressNumber,
                    address_complement: addressComplement,
                    address_neighborhood: addressNeighborhood,
                    address_city: addressCity,
                    address_state: addressState
                })
                .eq('id', session.user.id)
                .select()
                .single();

            if (error) throw error;

            // Update local context
            updateUser({
                name: updated.full_name,
                phone: updated.phone,
                avatar: updated.avatar_url,
                doc: updated.doc,
                company_name: updated.company_name,
                state_registration: updated.state_registration,
                pix_key: updated.pix_key,
                address_zip: updated.address_zip,
                address_street: updated.address_street,
                address_number: updated.address_number,
                address_complement: updated.address_complement,
                address_neighborhood: updated.address_neighborhood,
                address_city: updated.address_city,
                address_state: updated.address_state
            });
            setSuccess(true);

            setTimeout(() => setSuccess(false), 3000);
        } catch (error: any) {
            console.error("Erro ao salvar:", error);
            alert("Erro ao salvar perfil: " + (error.message || "Erro desconhecido"));
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="p-4 lg:p-8 space-y-8">
            <div>
                <h1 className="text-2xl font-black mb-1">Configurações</h1>
                <p className="text-xs text-slate-500 font-medium uppercase tracking-wider">Perfil e Ajustes da Conta</p>
            </div>

            {/* Tabs */}
            <div className="flex items-center gap-1 bg-slate-100 dark:bg-slate-800/50 p-1.5 rounded-2xl w-fit">
                <button
                    onClick={() => setActiveTab("perfil")}
                    className={cn(
                        "px-6 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2",
                        activeTab === "perfil" ? "bg-white dark:bg-slate-800 text-primary shadow-sm" : "text-slate-500 hover:text-slate-700"
                    )}
                >
                    <User size={14} />
                    Meu Perfil
                </button>
                <button
                    onClick={() => setActiveTab("fiscal")}
                    className={cn(
                        "px-6 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2",
                        activeTab === "fiscal" ? "bg-white dark:bg-slate-800 text-primary shadow-sm" : "text-slate-500 hover:text-slate-700"
                    )}
                >
                    <FileText size={14} />
                    Dados Fiscais
                </button>
                <button
                    onClick={() => setActiveTab("bancario")}
                    className={cn(
                        "px-6 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2",
                        activeTab === "bancario" ? "bg-white dark:bg-slate-800 text-primary shadow-sm" : "text-slate-500 hover:text-slate-700"
                    )}
                >
                    <CreditCard size={14} />
                    Dados Bancários
                </button>
                <button
                    onClick={() => setActiveTab("seguranca")}
                    className={cn(
                        "px-6 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2",
                        activeTab === "seguranca" ? "bg-white dark:bg-slate-800 text-primary shadow-sm" : "text-slate-500 hover:text-slate-700"
                    )}
                >
                    <ShieldCheck size={14} />
                    Segurança
                </button>
            </div>

            <div className="bg-white dark:bg-slate-800 rounded-3xl border border-slate-200 dark:border-slate-800 overflow-hidden shadow-sm">
                <div className="p-6 md:p-8">
                    {activeTab === "perfil" && (
                        <div className="space-y-8 animate-in fade-in duration-300">
                            {/* Avatar Section */}
                            <div className="flex flex-col md:flex-row items-center gap-6 pb-8 border-b border-slate-50 dark:border-slate-800">
                                <div className="relative group">
                                    <div className="size-24 rounded-3xl bg-primary/10 border-4 border-white dark:border-slate-800 shadow-xl overflow-hidden flex items-center justify-center text-primary font-black text-2xl">
                                        {currentUser.avatar ? (
                                            <img src={currentUser.avatar} alt="Profile" className="w-full h-full object-cover" />
                                        ) : (
                                            currentUser.name.charAt(0)
                                        )}
                                    </div>
                                    <button className="absolute -bottom-2 -right-2 size-8 bg-primary text-white rounded-xl shadow-lg flex items-center justify-center hover:scale-110 transition-transform">
                                        <ImageIcon size={14} />
                                    </button>
                                </div>
                                <div className="text-center md:text-left">
                                    <h3 className="text-lg font-bold">Foto de Perfil</h3>
                                    <p className="text-xs text-slate-500 mb-4 font-medium">JPG, GIF ou PNG. Tamanho máximo de 2MB.</p>
                                    <div className="flex gap-2">
                                        <button className="px-4 py-2 bg-primary text-white text-[10px] font-bold rounded-lg shadow-lg shadow-primary/20">Alterar Foto</button>
                                        <button className="px-4 py-2 bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 text-[10px] font-bold rounded-lg hover:bg-slate-200 transition-all">Remover</button>
                                    </div>
                                </div>
                            </div>

                            {/* Form Grid */}
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Nome Completo</label>
                                    <input
                                        type="text"
                                        value={name}
                                        onChange={(e) => setName(e.target.value)}
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary transition-all"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">E-mail Profissional</label>
                                    <input
                                        type="email"
                                        value={currentUser.email}
                                        disabled
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary transition-all opacity-50 cursor-not-allowed"
                                        title="Email deve ser alterado via segurança do Supabase"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Telefone / WhatsApp</label>
                                    <input
                                        type="text"
                                        value={phone}
                                        onChange={(e) => setPhone(e.target.value)}
                                        placeholder="(00) 00000-0000"
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary transition-all"
                                    />
                                </div>
                                <div className="space-y-2 md:col-span-2">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">URL do Avatar</label>
                                    <input
                                        type="text"
                                        value={avatarUrl}
                                        onChange={(e) => setAvatarUrl(e.target.value)}
                                        placeholder="https://exemplo.com/foto.jpg"
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary transition-all"
                                    />
                                </div>
                            </div>

                            <div className="flex justify-end pt-4 items-center gap-4">
                                {success && (
                                    <span className="text-emerald-500 text-xs font-bold animate-pulse">✓ Salvo com sucesso!</span>
                                )}
                                <button
                                    onClick={handleSaveProfile}
                                    disabled={loading}
                                    className="bg-primary text-white px-8 py-3 rounded-2xl font-bold text-sm shadow-xl shadow-primary/20 hover:scale-[1.02] transition-all flex items-center gap-2 disabled:opacity-50"
                                >
                                    {loading ? (
                                        <Save size={18} className="animate-spin" />
                                    ) : (
                                        <Save size={18} />
                                    )}
                                    {loading ? 'Salvando...' : 'Salvar Alterações'}
                                </button>
                            </div>
                        </div>
                    )}

                    {activeTab === "fiscal" && (
                        <div className="space-y-8 animate-in fade-in duration-300">
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                <div className="space-y-2 md:col-span-1">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">CPF / CNPJ</label>
                                    <input
                                        type="text"
                                        value={doc}
                                        onChange={(e) => setDoc(e.target.value)}
                                        placeholder="000.000.000-00"
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary"
                                    />
                                </div>
                                <div className="space-y-2 md:col-span-2">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Razão Social / Nome Fantasia</label>
                                    <input
                                        type="text"
                                        value={companyName}
                                        onChange={(e) => setCompanyName(e.target.value)}
                                        placeholder="Nome da sua empresa"
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Inscrição Estadual</label>
                                    <input
                                        type="text"
                                        value={stateRegistration}
                                        onChange={(e) => setStateRegistration(e.target.value)}
                                        placeholder="Isento"
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">CEP</label>
                                    <input
                                        type="text"
                                        value={addressZip}
                                        onChange={(e) => setAddressZip(e.target.value)}
                                        placeholder="00000-000"
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary transition-all"
                                    />
                                </div>
                                <div className="space-y-2 flex-grow md:col-span-2 lg:col-span-1">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Logradouro</label>
                                    <input
                                        type="text"
                                        value={addressStreet}
                                        onChange={(e) => setAddressStreet(e.target.value)}
                                        placeholder="Rua, Avenida, etc."
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary transition-all"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Número</label>
                                    <input
                                        type="text"
                                        value={addressNumber}
                                        onChange={(e) => setAddressNumber(e.target.value)}
                                        placeholder="123"
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary transition-all"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Complemento</label>
                                    <input
                                        type="text"
                                        value={addressComplement}
                                        onChange={(e) => setAddressComplement(e.target.value)}
                                        placeholder="Apto, Sala, etc."
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary transition-all"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Bairro</label>
                                    <input
                                        type="text"
                                        value={addressNeighborhood}
                                        onChange={(e) => setAddressNeighborhood(e.target.value)}
                                        placeholder="Seu bairro"
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary transition-all"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Cidade</label>
                                    <input
                                        type="text"
                                        value={addressCity}
                                        onChange={(e) => setAddressCity(e.target.value)}
                                        placeholder="Sua cidade"
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary transition-all"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Estado (UF)</label>
                                    <input
                                        type="text"
                                        value={addressState}
                                        onChange={(e) => setAddressState(e.target.value)}
                                        placeholder="SP"
                                        maxLength={2}
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary transition-all"
                                    />
                                </div>
                            </div>
                            <div className="flex justify-end pt-4 items-center gap-4">
                                {success && (
                                    <span className="text-emerald-500 text-xs font-bold animate-pulse">✓ Salvo com sucesso!</span>
                                )}
                                <button
                                    onClick={handleSaveProfile}
                                    disabled={loading}
                                    className="bg-primary text-white px-8 py-3 rounded-2xl font-bold text-sm shadow-xl shadow-primary/20 hover:scale-[1.02] transition-all flex items-center gap-2 disabled:opacity-50"
                                >
                                    {loading ? <Save size={18} className="animate-spin" /> : <Save size={18} />}
                                    {loading ? 'Salvando...' : 'Salvar Dados Fiscais'}
                                </button>
                            </div>
                        </div>
                    )}

                    {activeTab === "bancario" && (
                        <div className="space-y-8 animate-in fade-in duration-300">
                            <div className="bg-indigo-50 dark:bg-indigo-900/10 border border-indigo-100 dark:border-indigo-900/30 p-4 rounded-2xl flex gap-3 text-indigo-700 dark:text-indigo-400">
                                <CreditCard size={20} className="shrink-0" />
                                <p className="text-xs font-medium">Informe sua chave PIX para o recebimento automático de comissões e resgates.</p>
                            </div>

                            <div className="space-y-4">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Chave PIX (E-mail, CPF, Celular ou Aleatória)</label>
                                    <input
                                        type="text"
                                        value={pixKey}
                                        onChange={(e) => setPixKey(e.target.value)}
                                        placeholder="Sua chave PIX"
                                        className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-900 border-none rounded-xl text-sm focus:ring-2 focus:ring-primary"
                                    />
                                </div>
                            </div>

                            <div className="flex justify-end pt-4 items-center gap-4">
                                {success && (
                                    <span className="text-emerald-500 text-xs font-bold animate-pulse">✓ Salvo com sucesso!</span>
                                )}
                                <button
                                    onClick={handleSaveProfile}
                                    disabled={loading}
                                    className="bg-primary text-white px-8 py-3 rounded-2xl font-bold text-sm shadow-xl shadow-primary/20 hover:scale-[1.02] transition-all flex items-center gap-2 disabled:opacity-50"
                                >
                                    {loading ? <Save size={18} className="animate-spin" /> : <Save size={18} />}
                                    {loading ? 'Salvando...' : 'Salvar Dados Bancários'}
                                </button>
                            </div>
                        </div>
                    )}

                    {activeTab === "seguranca" && (
                        <div className="space-y-8 animate-in fade-in duration-300">
                            <div className="space-y-6">
                                <div className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-900/50 rounded-2xl border border-slate-100 dark:border-slate-800">
                                    <div className="flex gap-4 items-center">
                                        <div className="size-10 rounded-xl bg-primary/10 flex items-center justify-center text-primary">
                                            <Lock size={20} />
                                        </div>
                                        <div>
                                            <p className="text-sm font-bold">Autenticação em Duas Etapas</p>
                                            <p className="text-[10px] text-slate-500 font-medium">Adicione uma camada extra de segurança.</p>
                                        </div>
                                    </div>
                                    <button className="text-xs font-bold text-primary hover:underline">Configurar</button>
                                </div>

                                <div className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-900/50 rounded-2xl border border-slate-100 dark:border-slate-800">
                                    <div className="flex gap-4 items-center">
                                        <div className="size-10 rounded-xl bg-orange-100 dark:bg-orange-900/20 flex items-center justify-center text-orange-600">
                                            <AlertCircle size={20} />
                                        </div>
                                        <div>
                                            <p className="text-sm font-bold">Alterar Senha</p>
                                            <p className="text-[10px] text-slate-500 font-medium">Sua senha foi alterada há 64 dias.</p>
                                        </div>
                                    </div>
                                    <button className="text-xs font-bold text-orange-600 hover:underline">Alterar Agora</button>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}
